<?php

namespace Tests\Feature;

use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Log;
use Tests\TestCase;

final class GeminiApiDiagnosticTest extends TestCase
{
    public function test_gemini_api_key_is_configured(): void
    {
        $apiKey = config('services.gemini.key');
        $this->assertNotNull($apiKey, 'GEMINI_API_KEY is not configured');
        $this->assertNotEmpty($apiKey, 'GEMINI_API_KEY is empty');
    }

    public function test_gemini_model_is_configured(): void
    {
        $model = config('services.gemini.cin.model');
        $this->assertNotNull($model, 'GEMINI_CIN_MODEL is not configured');
        $this->assertNotEmpty($model, 'GEMINI_CIN_MODEL is empty');
    }

    public function test_gemini_api_connection(): void
    {
        $apiKey = config('services.gemini.key');
        $model = config('services.gemini.cin.model', 'gemini-2.0-flash-exp');

        if (empty($apiKey)) {
            $this->markTestSkipped('GEMINI_API_KEY not configured');
        }

        $endpoint = 'https://generativelanguage.googleapis.com/v1beta/interactions';

        $payload = [
            'model' => $model,
            'system_instruction' => 'You are a test assistant.',
            'input' => [
                [
                    'type' => 'text',
                    'text' => 'Say "Hello" in JSON format: {"response": "Hello"}',
                ],
            ],
            'response_format' => [
                'type' => 'text',
                'mime_type' => 'application/json',
            ],
            'generation_config' => [
                'max_output_tokens' => 100,
            ],
            'store' => false,
            'background' => false,
        ];

        $response = Http::acceptJson()
            ->asJson()
            ->connectTimeout(10)
            ->timeout(30)
            ->withHeader('x-goog-api-key', $apiKey)
            ->withoutVerifying()
            ->post($endpoint, $payload);

        $this->assertNotNull($response, 'Response is null');
        $this->assertNotNull($response->status(), 'Response status is null');

        echo "\n=== API Response ===\n";
        echo "Status: " . $response->status() . "\n";
        echo "Body: " . $response->body() . "\n";
        echo "==================\n";

        if ($response->status() === 401) {
            $this->fail('API key is invalid or unauthorized');
        }

        if ($response->status() === 403) {
            $this->fail('API key does not have permission to access this model');
        }

        if ($response->status() === 404) {
            $this->fail('Model not found: ' . $model);
        }

        $this->assertTrue($response->successful(), 'API request failed with status ' . $response->status());
    }

    public function test_gemini_api_with_image(): void
    {
        $apiKey = config('services.gemini.key');
        $model = config('services.gemini.cin.model', 'gemini-2.0-flash-exp');

        if (empty($apiKey)) {
            $this->markTestSkipped('GEMINI_API_KEY not configured');
        }

        // Create a simple 1x1 pixel image
        $imageData = base64_encode(
            pack('H*', '')
        );

        $endpoint = 'https://generativelanguage.googleapis.com/v1beta/interactions';

        $payload = [
            'model' => $model,
            'system_instruction' => 'Describe the image in one word.',
            'input' => [
                [
                    'type' => 'text',
                    'text' => 'IMAGE A follows.',
                ],
                [
                    'type' => 'image',
                    'data' => $imageData,
                    'mime_type' => 'image/gif',
                ],
                [
                    'type' => 'text',
                    'text' => 'Describe in JSON: {"description": "word"}',
                ],
            ],
            'response_format' => [
                'type' => 'text',
                'mime_type' => 'application/json',
            ],
            'generation_config' => [
                'max_output_tokens' => 100,
            ],
            'store' => false,
            'background' => false,
        ];

        $response = Http::acceptJson()
            ->asJson()
            ->connectTimeout(10)
            ->timeout(60)
            ->withHeader('x-goog-api-key', $apiKey)
            ->withoutVerifying()
            ->post($endpoint, $payload);

        echo "\n=== Image API Response ===\n";
        echo "Status: " . $response->status() . "\n";
        echo "Body: " . $response->body() . "\n";
        echo "========================\n";

        $this->assertTrue($response->successful(), 'Image API request failed with status ' . $response->status());
    }
}
